from __future__ import annotations


def render_kuzu_risk_page() -> str:
    return """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kuzu 关联风险扩散</title><style>
:root{font-family:"Microsoft YaHei",Arial,sans-serif;color:#e5e7eb;background:#0b1220}*{box-sizing:border-box}body{margin:0}.bar{padding:14px 22px;border-bottom:1px solid #263246;background:#111827;display:flex;gap:14px;align-items:center}.back{color:#93c5fd;text-decoration:none;border:1px solid #2563eb;border-radius:4px;padding:5px 9px}.brand{font-size:18px;font-weight:700}.hint{font-size:12px;color:#aeb7c2}.stage{padding:18px;max-width:1500px;margin:auto}.tools{display:flex;gap:12px;align-items:center;margin-bottom:12px;flex-wrap:wrap}.tools input{width:72px;background:#111827;color:#fff;border:1px solid #475569;border-radius:4px;padding:7px}.tools input[type=checkbox]{width:auto;padding:0;accent-color:#2563eb}.tools button{background:#2563eb;color:#fff;border:0;border-radius:4px;padding:8px 12px;cursor:pointer}.legend{display:flex;gap:10px;font-size:12px;color:#cbd5e1;flex-wrap:wrap}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:4px}.board{height:390px;border:1px solid #334155;border-radius:8px;background:#101826;overflow:hidden}.board canvas{width:100%;height:100%;display:block;touch-action:none;cursor:grab}.board canvas:active{cursor:grabbing}.caption{padding:10px 0 16px;color:#b8cce1;font-size:13px}.caption b{color:#fff}.caption span{color:#85d3ff}.detail{border-top:1px solid #334155;padding-top:15px}.detail h2{font-size:16px;margin:0 0 12px}.flow{display:grid;grid-template-columns:135px 205px minmax(0,1fr);gap:26px;align-items:center}.subject{text-align:center;position:relative}.subject:after{content:"";position:absolute;top:50%;left:100%;width:26px;border-top:2px solid #58c4ff}.subject b{display:flex;align-items:center;justify-content:center;width:92px;height:92px;border-radius:50%;margin:auto;background:#ff2638;border:3px solid #ffd6dc;font-size:18px;box-shadow:0 0 0 7px rgba(255,38,56,.14)}.subject small{display:block;color:#a8bfd7;font-size:12px;margin-top:8px}.groups{display:grid;gap:8px}.group{font:inherit;text-align:left;color:#dceaf9;background:#10233c;border:1px solid #365879;border-left:6px solid #6d87a7;border-radius:7px;padding:9px 10px;cursor:pointer}.group strong{display:block;font-size:13px}.group span{display:block;color:#9fb6cf;font-size:11px;margin-top:3px}.group.active{border-left-color:#58c4ff;background:#183959;outline:1px solid #58c4ff}.cluster{border:1px solid #355573;border-radius:8px;background:#0e1c2f;padding:11px 13px}.cluster header{display:flex;justify-content:space-between;gap:8px;font-size:14px}.cluster header span{font-size:12px;color:#9fb9d5}.people{display:flex;flex-wrap:wrap;gap:7px;margin-top:9px}.person{min-width:78px;padding:7px 9px;border-radius:5px;background:#602d38;border:1px solid #e76b7d;text-align:center;font-size:12px}.person.mid{background:#654126;border-color:#eaa05a}.person.stop{background:#164a3e;border-color:#3ec589}.person strong{display:block}.person small{display:block;color:#d7e4f2;font-size:11px;margin-top:2px}.empty{color:#9fb6cf;font-size:13px}@media(max-width:700px){.bar{padding:12px}.stage{padding:14px}.board{height:340px}.flow{grid-template-columns:1fr;gap:13px}.subject{display:flex;align-items:center;gap:13px;text-align:left}.subject b{margin:0;flex:0 0 auto}.subject:after{display:none}.groups{grid-template-columns:repeat(2,minmax(0,1fr))}}</style></head><body>
<header class="bar"><a class="back" id="back" href="/">← 返回账户</a><span class="brand">Kuzu 关联风险扩散</span><span class="hint">上方按账户扩散深度定位；下方查看关系证据</span><span class="hint" id="status">读取中…</span></header>
<main class="stage"><div class="tools"><label>扩散阈值 <input id="threshold" type="number" min="1" max="100" value="20"></label><label title="全平台同步开平仓核验会明显增加耗时"><input id="includeToxic" type="checkbox"> 包含 Toxic 同步订单（较慢）</label><button id="reload">重新计算</button><span class="legend"><span><i class="dot" style="background:#ff2638"></i>问题账户</span><span><i class="dot" style="background:#ff6976"></i>高传播分</span><span><i class="dot" style="background:#f5a64b"></i>更外层</span><span><i class="dot" style="background:#35c285"></i>停止扩散</span><span><i class="dot" style="background:#58c4ff"></i>当前账户路径</span></span></div><div class="board"><canvas id="overview" aria-label="按扩散深度定位的全局关系图"></canvas></div><div class="caption"><b id="location">当前查看：-</b> <span id="path">关系路径说明：选择上方账户查看它如何与问题账户相连。</span></div><section class="detail"><h2>当前账户细查</h2><div class="flow"><div class="subject"><b id="selected">-</b><small id="selectedNote">-</small></div><div class="groups" id="groups"></div><article class="cluster"><header><b id="evidence">-</b><span id="evidenceNote">-</span></header><div class="people" id="people"></div></article></div></section></main>
<script>
const canvas=document.getElementById('overview'),ctx=canvas.getContext('2d'),threshold=document.getElementById('threshold'),status=document.getElementById('status'),groups=document.getElementById('groups'),people=document.getElementById('people');let data=null,selectedId='',activeType='',view={scale:1,x:0,y:0},drag=null,layout=new Map();const radar=document.createElement('div');radar.setAttribute('aria-label','关系扩散扫描中');Object.assign(radar.style,{display:'none',position:'absolute',inset:'0',pointerEvents:'none',overflow:'hidden'});canvas.parentElement.style.position='relative';radar.innerHTML='<svg viewBox="0 0 1 1" width="100%" height="100%" aria-hidden="true"><g id="radarSweep" transform="translate(.5 .5)"><path id="radarFan" d="M0 0 L0 -1 A1 1 0 0 1 .31 -.95 Z" fill="rgba(70,210,255,.18)"><animateTransform attributeName="transform" type="rotate" from="0" to="360" dur="1.8s" repeatCount="indefinite"/></path><line id="radarBeam" x1="0" y1="0" x2="0" y2="-1" stroke="rgba(100,225,255,.9)" stroke-width="2.4"><animateTransform attributeName="transform" type="rotate" from="0" to="360" dur="1.8s" repeatCount="indefinite"/></line></g></svg>';canvas.parentElement.append(radar);const radarSvg=radar.querySelector('svg'),radarSweep=radar.querySelector('#radarSweep'),radarFan=radar.querySelector('#radarFan'),radarBeam=radar.querySelector('#radarBeam');function positionRadar(){const subject=accounts().find(node=>node.isSubject),point=subject&&layout.get(subject.id),bounds=canvas.getBoundingClientRect();if(!point||!bounds.width||!bounds.height)return;const radius=Math.hypot(bounds.width,bounds.height),angle=Math.PI/10,endX=Math.sin(angle)*radius,endY=-Math.cos(angle)*radius,x=point.x*view.scale+view.x,y=point.y*view.scale+view.y;radarSvg.setAttribute('viewBox','0 0 '+bounds.width+' '+bounds.height);radarFan.setAttribute('d','M0 0 L0 -'+radius+' A '+radius+' '+radius+' 0 0 1 '+endX+' '+endY+' Z');radarBeam.setAttribute('y2',String(-radius));radarSweep.setAttribute('transform','translate('+x+' '+y+')')}new MutationObserver(()=>{radar.style.display=status.textContent.includes('后台扩散中')?'block':'none'}).observe(status,{childList:true,characterData:true,subtree:true});
function relationMap(){return new Map((data.relationTypes||[]).map(x=>[x.id,x.label]))}function accounts(){return data.entities.filter(x=>x.type==='account')}function byId(){return new Map(data.entities.map(x=>[x.id,x]))}function primary(node){return (node.scoreLedger||[])[0]||null}function directSubjectEdge(node){const subject=accounts().find(item=>item.isSubject);if(!subject||node.isSubject)return null;return data.relationships.find(edge=>(edge.source===subject.id&&edge.target===node.id)||(edge.target===subject.id&&edge.source===node.id))||null}function parent(node){const direct=directSubjectEdge(node);if(direct){const subject=accounts().find(item=>item.isSubject);return subject||null}let current=node,seen=new Set(),map=byId();while(current&&!seen.has(current.id)){seen.add(current.id);const ledger=primary(current);if(!ledger)return null;const from=map.get(ledger.from);if(!from)return null;if(from.type==='account')return from;current=from}return null}
function accountDepth(node){if(node.isSubject)return 0;let depth=0,current=node,seen=new Set();while(current&&!current.isSubject&&!seen.has(current.id)){seen.add(current.id);const next=parent(current);if(!next){return Math.max(1,Math.ceil(Number(node.hops||1)/2))}depth++;current=next}return Math.max(1,depth)}function branchType(node){const direct=directSubjectEdge(node);if(direct)return direct.type;const ledger=primary(node);return ledger?ledger.type:'unknown'}function route(node){const result=[];let current=node,seen=new Set();while(current&&!seen.has(current.id)){result.unshift(current);seen.add(current.id);current=parent(current)}return result}
function color(node,depth){if(node.isSubject)return'#ff2638';if(!node.expandable)return'#35c285';const intensity=Math.max(.15,Math.min(1,(Number(node.score||0)/100)*Math.pow(.78,Math.max(0,depth-1))));return `hsl(12 90% ${78-intensity*38}%)`}
function renderOverview(){if(!data)return;const r=canvas.getBoundingClientRect(),w=r.width,h=r.height,all=accounts(),subject=all.find(x=>x.isSubject),types=[...new Set(all.filter(x=>!x.isSubject).map(branchType))].sort(),radius=Math.max(52,Math.min(w,h)*.15);layout=new Map();layout.set(subject.id,{x:w*.52,y:h*.53,depth:0,type:'subject'});types.forEach((type,index)=>{const items=all.filter(x=>!x.isSubject&&branchType(x)===type).sort((a,b)=>Number(b.score)-Number(a.score));const base=-Math.PI/2+index*(Math.PI*2/types.length);items.forEach((node,itemIndex)=>{const depth=Math.min(4,accountDepth(node)),offset=(itemIndex-(items.length-1)/2)*Math.min(.13,.8/Math.max(1,items.length));layout.set(node.id,{x:w*.52+Math.cos(base+offset)*radius*depth,y:h*.53+Math.sin(base+offset)*radius*depth,depth,type})})});ctx.fillStyle='#101826';ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(view.x,view.y);ctx.scale(view.scale,view.scale);for(let ring=1;ring<=4;ring++){ctx.strokeStyle='rgba(112,144,178,.45)';ctx.lineWidth=1;ctx.setLineDash([4,6]);ctx.beginPath();ctx.arc(w*.52,h*.53,radius*ring,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#93acc6';ctx.font='11px Microsoft YaHei';ctx.fillText('第 '+ring+' 圈 · '+all.filter(x=>accountDepth(x)===ring).length+' 个账户',w*.52-radius*ring-58,h*.53-radius*ring+7)}const selected=byId().get(selectedId)||subject,routeIds=new Set(route(selected).map(x=>x.id)),pathNodes=route(selected);for(let i=1;i<pathNodes.length;i++){const a=layout.get(pathNodes[i-1].id),b=layout.get(pathNodes[i].id);if(a&&b){ctx.strokeStyle='#58c4ff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}for(const node of all){const p=layout.get(node.id),depth=p.depth,current=node.id===selectedId,onRoute=routeIds.has(node.id),size=node.isSubject?12:depth===1?5.5:depth===2?4.5:3.6;if(current){ctx.strokeStyle='rgba(88,196,255,.36)';ctx.lineWidth=8;ctx.beginPath();ctx.arc(p.x,p.y,15,0,Math.PI*2);ctx.stroke()}else if(onRoute){ctx.strokeStyle='rgba(88,196,255,.18)';ctx.lineWidth=5;ctx.beginPath();ctx.arc(p.x,p.y,size+4,0,Math.PI*2);ctx.stroke()}ctx.fillStyle=color(node,depth);ctx.globalAlpha=depth>=3?.65:1;ctx.beginPath();ctx.arc(p.x,p.y,current?7:size,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;if(current||node.isSubject){ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,current?7:size,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#fff';ctx.font='500 11px Microsoft YaHei';ctx.textAlign='center';ctx.fillText(node.label,p.x,p.y-(node.isSubject?19:16));ctx.textAlign='start'}}ctx.restore();positionRadar()}
function typeGroups(node){const result=[],labels=relationMap();for(const edge of data.relationships){if(edge.source===node.id||edge.target===node.id){if(!result.includes(edge.type))result.push(edge.type)}}for(const ledger of node.scoreLedger||[]){if(!result.includes(ledger.type))result.push(ledger.type)}return result.sort((a,b)=>(labels.get(a)||a).localeCompare(labels.get(b)||b))}function peers(node,type){const map=byId(),ids=new Set(),connectors=new Set([node.id]);if(type === 'ib_direct_account'){for(const edge of data.relationships)if(edge.type===type&&(edge.source===node.id||edge.target===node.id)){const other=edge.source===node.id?edge.target:edge.source;const item=map.get(other);if(item&&item.type==='account'&&item.id!==node.id)ids.add(item.id)}}else{for(const edge of data.relationships)if(edge.type===type&&(edge.source===node.id||edge.target===node.id))connectors.add(edge.source===node.id?edge.target:edge.source);for(const connector of connectors)for(const edge of data.relationships)if(edge.type===type&&(edge.source===connector||edge.target===connector)){const other=edge.source===connector?edge.target:edge.source;const item=map.get(other);if(item&&item.type==='account'&&item.id!==node.id)ids.add(item.id)}}return [...ids].map(id=>map.get(id)).sort((a,b)=>Number(b.score)-Number(a.score)).slice(0,8)}
function relationshipTitle(type,labels){const titles={login_ip:'当前登录 IP 相同',top_ib_group:'同属顶级 IB 群组（仅聚合）',rebate:'存在返佣链路记录',ib_direct_account:'直属上级 IB 本人交易账户',ib_owned_account:'IB 本人名下交易账户',direct_ib:'CRM 直属上级 IB',crm_owner:'CRM 账户归属',same_crm_user:'同一 CRM 客户',ea_feature:'EA / 路由特征相同',copy_order:'存在同步订单',copy_group:'同一跟单组',toxic_sync_same:'同向同步开平仓',toxic_sync_opposite:'反向同步开平仓'};return titles[type]||labels.get(type)||type}
function relationshipExplanation(type){const explanations={login_ip:'该账户与问题账户当前 LastIP 相同；仅代表当前登录 IP 重合，不等同于同一设备。',top_ib_group:'与问题账户同属同一顶级 IB 群组；只显示群组统计，不会自动把全部下属账户扩散出来。',rebate:'问题账户与这些账户之间存在返佣收款或返佣链路记录。',ib_direct_account:'问题账户的直属上级 IB 本人名下交易账户，不是该 IB 的下属客户账户。',ib_owned_account:'该交易账户归属该 IB 本人。',direct_ib:'CRM 层级显示该 IB 是问题账户 CRM 用户的直属上级。',crm_owner:'该交易账户对应问题账户所属的 CRM 用户，用于解释账户归属。',same_crm_user:'这些交易账户属于同一个 CRM 客户。',ea_feature:'订单 Comment / ExpertID / 路由特征存在匹配。',copy_order:'存在符合规则的同步开仓和/或平仓订单。',copy_group:'归属于同一已识别的跟单来源或组。',toxic_sync_same:'不同账户订单在开仓、平仓时间和方向上出现同步。',toxic_sync_opposite:'不同账户订单在开仓、平仓时间上同步但方向相反。'};return explanations[type]||'这是已读取到的关系证据；请结合右侧原始依据核验。'}
function relationPathText(node){if(node.isSubject)return'这是问题账户，调查从该账户开始。';const nodes=route(node),labels=relationMap(),steps=[];for(let index=1;index<nodes.length;index++){const item=nodes[index];steps.push('通过「'+relationshipTitle(branchType(item),labels)+'」识别到账户 '+item.label)}return '从问题账户 '+(nodes[0]?nodes[0].label:node.label)+' 出发，'+(steps.length?steps.join('；'):'识别到该关联账户')+'。'}
function renderDetail(){const node=byId().get(selectedId);if(!node)return;const depth=accountDepth(node),labels=relationMap(),types=typeGroups(node);if(!types.length)types.push(branchType(node));if(!types.includes(activeType))activeType=types[0];document.getElementById('location').textContent='当前查看：'+node.label+(node.isSubject?'（问题账户 / 调查起点）':'（与问题账户相隔第 '+depth+' 层）');document.getElementById('path').textContent='关系路径说明：'+relationPathText(node);document.getElementById('selected').textContent=node.label;document.getElementById('selectedNote').textContent=node.isSubject?'问题账户 / 第 0 层 / 传播分 100.0':'与问题账户相隔第 '+depth+' 层 / 传播分 '+Number(node.score||0).toFixed(1);groups.replaceChildren();for(const type of types){const button=document.createElement('button');button.type='button';button.className='group'+(type===activeType?' active':'');const title=document.createElement('strong');title.textContent=relationshipTitle(type,labels);const note=document.createElement('span');note.textContent=relationshipExplanation(type);button.append(title,note);button.addEventListener('click',()=>{activeType=type;renderDetail()});groups.append(button)}const related=peers(node,activeType),edge=data.relationships.find(x=>x.type===activeType&&(x.source===node.id||x.target===node.id)),explanation=relationshipExplanation(activeType);document.getElementById('evidence').textContent='关联逻辑：'+relationshipTitle(activeType,labels);document.getElementById('evidenceNote').textContent=explanation+' '+((edge&&edge.evidence&&edge.evidence[0])?('原始依据：'+edge.evidence[0]):('当前显示 '+related.length+' 个关联账户'));people.replaceChildren();if(!related.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='该线索未发现可显示的其他账户。';people.append(empty)}for(const item of related){const card=document.createElement('div');card.className='person'+(!item.expandable?' stop':accountDepth(item)>1?' mid':'');const name=document.createElement('strong');name.textContent=item.label;const note=document.createElement('small');note.textContent='与问题账户相隔第 '+accountDepth(item)+' 层 · 传播分 '+Number(item.score||0).toFixed(1);card.append(name,note);card.addEventListener('click',()=>{selectedId=item.id;activeType='';renderOverview();renderDetail()});people.append(card)}}
function fit(){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);renderOverview()}function world(ev){const r=canvas.getBoundingClientRect();return{x:(ev.clientX-r.left-view.x)/view.scale,y:(ev.clientY-r.top-view.y)/view.scale}}window.addEventListener('resize',fit);canvas.addEventListener('wheel',ev=>{ev.preventDefault();const r=canvas.getBoundingClientRect(),before=world(ev),factor=ev.deltaY<0?1.12:1/1.12,next=Math.max(.45,Math.min(2.5,view.scale*factor));view.scale=next;view.x=ev.clientX-r.left-before.x*next;view.y=ev.clientY-r.top-before.y*next;renderOverview()},{passive:false});canvas.addEventListener('pointerdown',ev=>{drag={x:ev.clientX,y:ev.clientY,viewX:view.x,viewY:view.y};canvas.setPointerCapture(ev.pointerId)});canvas.addEventListener('pointermove',ev=>{if(!drag)return;view.x=drag.viewX+ev.clientX-drag.x;view.y=drag.viewY+ev.clientY-drag.y;renderOverview()});canvas.addEventListener('pointerup',()=>{drag=null});canvas.addEventListener('click',ev=>{if(!data)return;const point=world(ev);let closest=null,distance=15;for(const node of accounts()){const p=layout.get(node.id),d=Math.hypot(point.x-p.x,point.y-p.y);if(d<distance){closest=node;distance=d}}if(closest){selectedId=closest.id;activeType='';renderOverview();renderDetail()}});
const params=new URLSearchParams(location.search),target=params.get('account')||'',includeToxic=document.getElementById('includeToxic');let controller=null,pollTimer=null;if(target)document.getElementById('back').href='/account/'+encodeURIComponent(target)+'?'+params.toString();function apiUrl(value){if(!target)return '/api/kuzu-risk/graph?threshold='+value;const query=new URLSearchParams();for(const key of ['platform','server','symbol'])if(params.get(key))query.set(key,params.get(key));query.set('threshold',String(value));if(includeToxic.checked)query.set('include_toxic','true');return '/api/accounts/by-login/'+encodeURIComponent(target)+'/relationship-network?'+query.toString()}function queuePoll(){clearTimeout(pollTimer);pollTimer=setTimeout(()=>load(true),1200)}async function load(isPoll=false){if(controller)return;controller=new AbortController();const active=controller,value=Math.max(1,Math.min(100,Number(threshold.value)||20));threshold.value=value;if(!isPoll)status.textContent=includeToxic.checked?'后台扩散与 Toxic 同步订单准备中…':'关系后台扩散准备中…';const timeout=setTimeout(()=>active.abort(),8000);try{const response=await fetch(apiUrl(value),{cache:'no-store',signal:active.signal});if(!response.ok)throw new Error();const next=await response.json();const nextAccounts=Array.isArray(next.entities)?next.entities.filter(x=>x.type==='account'):[];if(!next.ok){status.textContent=(next.limitations||[])[0]||'图谱读取失败';return}if(!nextAccounts.length){status.textContent='关系后台扩散中：等待首批证据…';queuePoll();return}const hasSelected=nextAccounts.some(x=>x.id===selectedId);data=next;if(!hasSelected){selectedId=data.subjectId||nextAccounts.find(x=>x.isSubject)?.id||'';activeType='';view={scale:1,x:0,y:0}}fit();renderDetail();const progress=data.progress||{},expanded=Number(progress.expandedAccounts||data.summary?.discoveryAccountCount||0),pending=Number(progress.pendingAccounts||data.summary?.pendingAccountCount||0);if(data.inProgress){status.textContent='后台扩散中：已处理 '+expanded+' 个账户，待处理 '+pending+' 个；图谱会自动更新。';queuePoll()}else{status.textContent='规则 '+data.summary.ruleVersion+(data.truncated?' · 已触发安全节点/边上限':' · 已按阈值完成扩散')}}catch(error){status.textContent=error.name==='AbortError'?'图谱请求超时，后台任务仍会继续；正在重试。':'图谱读取失败';queuePoll()}finally{clearTimeout(timeout);if(controller===active)controller=null}}document.getElementById('reload').addEventListener('click',()=>{clearTimeout(pollTimer);selectedId='';activeType='';load()});load();
</script></body></html>"""
